import { shopPreviewHTML, shopSourceHTML, shopStatus } from './shop-sync.js';
import { escapeHTML as e, safeURL, assetURL, beijingInput, fromBeijing, displayTime, pendingFor, activeFor, statusLabel, allowHashNavigation, originalPlanSlots, sameUploadOwner } from './helpers.js';

const main = document.querySelector('#main'), dialog = document.querySelector('#dialog');
let db = {}, settings = {}, health = {}, config = {}, busy = false, dirty = false, pollVersion = '', images = [], plan = [], editingNote = null, report = null, toastTimer, renderedHash = location.hash, dialogToken = 0;
const route = () => location.hash.slice(1).split('/').filter(Boolean);
const rows = key => db[key] || [];
const get = (key,id) => rows(key).find(x => x.id === id);
const accountName = id => get('accounts',id)?.name || '账号已不可用';
const productName = id => get('products',id)?.name || '商品已不可用';
const approved = n => n.approvedRevision === n.revision && Boolean(n.contentApproval);
const field = (label,name,value='',type='text',extra='') => `<label>${e(label)}<input name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></label>`;
const area = (label,name,value='',extra='') => `<label>${e(label)}<textarea name="${e(name)}" ${extra}>${e(value)}</textarea></label>`;
const options = (items,current) => items.map(([value,label]) => `<option value="${e(value)}" ${value===current?'selected':''}>${e(label)}</option>`).join('');
const select = (label,name,items,current) => `<label>${e(label)}<select name="${e(name)}">${options(items,current)}</select></label>`;
const accountOptions = () => rows('accounts').map(a => [a.id,a.name]);
const button = (text,action,id='',primary=false,disabled=false) => `<button type="button" data-action="${action}" data-id="${e(id)}" ${primary?'class="primary"':''} ${disabled?'disabled':''}>${e(text)}</button>`;
const badge = status => `<span class="status ${e(status)}">${e(statusLabel(status))}</span>`;
const link = (url,label='打开来源') => safeURL(url) ? `<a href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>` : '<span class="muted">未提供有效来源链接</span>';
const img = (url,cls='',alt='商品图片') => assetURL(url) ? `<img src="${e(url)}" class="${cls}" alt="${e(alt)}" loading="lazy">` : '';
const head = (kicker,title,description='',actions='') => `<div class="page-head"><div><div class="overline">${e(kicker)}</div><h1>${e(title)}</h1>${description?`<p>${e(description)}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const empty = (title,text,action='') => `<div class="empty"><h2>${e(title)}</h2><p>${e(text)}</p>${action}</div>`;
const notice = text => `<div class="notice">${e(text)}</div>`;
const listNotes = batchId => rows('notes').filter(n => n.batchId === batchId);
function toast(message,error=false){ const el=document.querySelector('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?10000:5000); }
async function api(path,method='GET',data){ const response=await fetch('/api/'+path,{method,headers:data===undefined?{}:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await response.json();if(!response.ok)throw Error(result.error?.message || `请求失败 (${response.status})`);return result.data; }
async function load(){ const [data,s,h,c]=await Promise.all([api('state'),api('settings'),api('health'),api('config')]);db=data;settings=s;health=h;config=c;pollVersion=JSON.stringify(data);document.querySelector('#connection').textContent='本地服务在线 · 数据已保存';document.querySelector('#update-banner').hidden=true; }
const executorName = () => ({codex:'Codex CLI',workbuddy:'WorkBuddy',api:'LLM API'}[config.provider] || 'Codex CLI');
async function refresh(){await load();render();}
async function refreshSettings(form){const other=[...main.querySelectorAll('form[data-form]')].find(node=>node!==form),pending=other?[...other.elements].filter(node=>node.name).map(node=>({name:node.name,value:node.value,checked:node.checked,type:node.type})):[],unsaved=other?.dataset.unsaved==='true',kind=other?.dataset.form;await refresh();if(unsaved){const restored=main.querySelector(`form[data-form="${kind}"]`);for(const item of pending){const node=restored?.elements.namedItem(item.name);if(node){if(item.type==='checkbox')node.checked=item.checked;else node.value=item.value;}}if(restored)restored.dataset.unsaved='true';dirty=true;}}
function navigate(path){if(dirty&&!confirm('当前有未保存的修改，确定离开吗？'))return;dirty=false;if(location.hash==='#'+path)render();else location.hash=path;}
function steps(batch,index){return `<div class="steps"><span class="step-context">${e(productName(batch.productId))} / ${e(accountName(batch.accountId))}</span>${[['选题策划','batch'],['图文审核','review'],['发布排期','schedule']].map(([name,path],i)=>`<a class="step ${index===i?'active':''}" href="#${path}/${batch.id}"><i>${i+1}</i>${name}</a>`).join('')}</div>`;}
function tabs(active){return `<div class="tabs"><a href="#queue" class="${active==='queue'?'active':''}">笔记与排期</a><a href="#interactions" class="${active==='interactions'?'active':''}">点赞与留言</a></div>`;}
function render(){renderedHash=location.hash;dirty=false;editingNote=null;const [page='products',id,sub]=route();const nav=['product','batch','review','schedule'].includes(page)?'products':page==='interactions'?'queue':page;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});try{main.innerHTML=({products,product,batch,review,schedule,queue,jobs,research,settings:settingsPage,interactions}[page] || products)(id,sub);}catch(error){main.innerHTML=`<div class="screen-error"><h2>暂时无法显示此页面</h2><p>${e(error.message)}</p><a href="#products">返回商品</a></div>`;} }
function products(){return `<section class="products-page"><header class="products-heading"><div><div class="products-title"><h1>我的商品</h1><span class="product-count">${rows('products').length} 件商品</span></div><p>管理商品资料，开始下一次内容创作。</p></div>${rows('products').length?`<div class="actions">${button('同步店铺','shop-open')}${button('添加商品','product-new','',true)}</div>`:''}</header>`+(rows('products').length?`<div class="grid">${rows('products').map(p=>{const batches=rows('batches').filter(b=>b.productId===p.id),notes=rows('notes').filter(n=>n.productId===p.id);return `<article class="card product-card">${assetURL(p.images?.[0])?img(p.images[0],'product-image',p.name):'<div class="image-empty">还没有商品实拍图</div>'}<div class="card-body"><div class="pill-row"><span class="tag">${p.confirmed?'资料已确认':'资料待完善'}</span>${p.shopSource?`<span class="tag">${shopStatus(p.shopSource.status)}</span>`:''}<span class="tag">${[p.name,p.facts,p.images?.length,p.confirmed].filter(Boolean).length}/4 项资料</span></div><h2>${e(p.name)}</h2><div class="metric-row"><div><strong>${batches.length}</strong><span>创作批次</span></div><div><strong>${notes.filter(n=>!approved(n)).length}</strong><span>待审核笔记</span></div><div><strong>${notes.filter(approved).length}</strong><span>内容已通过</span></div></div><div class="actions"><a class="button primary" href="#product/${p.id}">进入商品 →</a>${button('编辑资料','product-edit',p.id)}</div></div></article>`}).join('')}</div>`:`<div class="products-empty"><div class="products-empty-icon" aria-hidden="true"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg></div><h2>添加你的第一件商品</h2><p>整理商品链接、参数和图片，<br>让每次创作都有可靠的素材。</p><div class="products-empty-actions">${button('添加商品','product-new','',true)}${button('同步店铺','shop-open')}</div><span class="products-empty-note">已有店铺商品？可从「同步店铺」查看连接状态。</span></div>`)+`</section>`;}
function product(id){const p=get('products',id);if(!p)throw Error('商品不存在');const batches=rows('batches').filter(b=>b.productId===id);return head('PRODUCT STUDIO',p.name,'商品资料是内容创作的事实依据。',button('编辑商品','product-edit',id)+button('创建批次','batch-new',id,true))+`<div class="two-col"><div><div class="card"><div class="section-head"><h2>创作批次</h2><span class="muted">${batches.length} 个批次</span></div>${batches.length?batches.map(b=>{const ns=listNotes(b.id);return `<div class="batch-item"><div><h3>${e(accountName(b.accountId))}</h3><p>${displayTime(b.createdAt)} · ${b.topicCount} 个候选 / 计划 ${b.targetCount} 篇</p><span class="tag">${ns.length} 篇笔记 · ${ns.filter(approved).length} 篇已审</span></div><div class="actions"><a class="button" href="#batch/${b.id}">选题</a><a class="button primary" href="#${ns.length?'review':'batch'}/${b.id}">${ns.length?'继续审核':'开始策划'} →</a></div></div>`}).join(''):empty('还没有创作批次','选择一个账号，先确认选题与逐张配图方案，再投入制作。',button('创建批次','batch-new',id,true))}</div></div><aside class="card"><div class="section-head"><h2>商品档案</h2><span class="tag">${p.confirmed?'已确认':'待确认'}</span></div>${assetURL(p.images?.[0])?img(p.images[0],'product-image',p.name):'<div class="image-empty">添加实拍图作为配图参考</div>'}<div class="uploads">${(p.images||[]).slice(1).map(url=>`<div class="asset">${img(url)}</div>`).join('')}</div>${shopSourceHTML(p)}<h3>已确认事实与卖点</h3><p class="raw-note">${e(p.facts||'尚未填写。不要将推测的参数作为商品事实。')}</p>${link(p.url,'商品链接')}<p class="muted">版本 ${p.version} · 修改资料会使相关笔记需要重新审核。</p></aside></div>`;}
function batch(id){const b=get('batches',id);if(!b)throw Error('批次不存在');const topics=rows('topics').filter(t=>t.batchId===id),selected=topics.filter(t=>t.confirmed),ns=listNotes(id);return steps(b,0)+head('CONTENT PLANNING','先选角度，再投入制作',`计划制作 ${b.targetCount} 篇，可按需要多选或少选。每篇图片数量由叙事决定。`,button('手工添加选题','topic-add',id,false,topics.length>=b.topicCount)+button('生成选题方案','plan',id,true,topics.length>0))+(!health.llmConfigured?notice('文案服务尚未配置。可先手工完善选题；自动规划不会静默回退为示例内容。'):'')+(topics.length?`<div class="grid">${topics.map(t=>`<article class="card topic-card ${t.confirmed?'selected':''}"><div class="topic-head"><span class="tag">${t.confirmed?'已选 · 方案通过':'未选入制作'}</span><span class="muted">${(t.imagePlan||[]).length} 张图</span></div><h2>${e(t.title)}</h2><p>${e(t.audience||'目标人群待补充')} · ${e(t.angle||'内容角度待补充')}</p><details><summary>查看配图方案与依据</summary><ol class="plan-list">${(t.imagePlan||[]).map(x=>`<li><b>${e(x.role)}</b><p>${e(x.prompt)}</p></li>`).join('')}</ol><p>图数理由：${e(t.imageCountReason||'待补充')}</p><p>商品依据：${e(t.factBasis||'待补充')}</p>${(t.evidenceIds||[]).map(id=>{const ev=get('evidence',id);return ev?`<p>${link(ev.sourceUrl||ev.url,'参考证据')} ${e(ev.reason||ev.candidate||'')}</p>`:`<p class="muted">引用证据：${e(id)}</p>`}).join('')}</details><div class="actions">${button('编辑方案','topic-edit',t.id)}${button(t.confirmed?'取消选择':'确认方案并选入',t.confirmed?'topic-unconfirm':'topic-confirm',t.id,!t.confirmed)}</div></article>`).join('')}</div>`:empty('还没有选题方案','可基于商品档案生成候选方案，或手工添加你已有的内容角度。'))+`<div class="bar"><div><strong>已选 ${selected.length} 篇 / 计划 ${b.targetCount} 篇</strong><p>共 ${(selected.reduce((n,t)=>n+(t.imagePlan?.length||0),0))} 张规划图片 · 费用暂不可估算</p></div><div class="actions">${ns.length?`<a class="button" href="#review/${id}">查看已有笔记</a>`:''}${button('选择服务并开始制作','generate-dialog',id,true,!selected.length)}</div></div>`;}
function review(id,noteId){const b=get('batches',id);if(!b)throw Error('批次不存在');const ns=listNotes(id);if(!ns.length)return steps(b,1)+empty('还没有图文草稿','先确认选题和配图方案，再生成或手工制作内容。',`<a class="button primary" href="#batch/${id}">返回选题</a>`);const n=ns.find(n=>n.id===noteId)||ns[0],p=get('products',n.productId);editingNote=n.id;images=[...n.images];return steps(b,1)+head('EDITORIAL REVIEW','逐篇审阅，连续处理','保存修改会产生新版本，并撤销旧版本的审核与发布授权。',`<a class="button" href="#jobs/${id}">生成任务</a>`)+`<div class="review"><aside class="card note-list">${ns.map(x=>`<a class="button note-item ${x.id===n.id?'active':''}" href="#review/${id}/${x.id}">${e(x.title)}<small>${approved(x)?'内容已通过':'待审核'} · v${x.revision}</small></a>`).join('')}</aside><section class="card note-editor"><form id="note-form" data-form="note" data-id="${n.id}">${field('标题','title',n.title,'text','required maxlength="200"')}${area('正文','body',n.body,'required')}<div class="row"><h3>图片与顺序</h3><span id="image-count" class="muted">${images.length} 张</span></div><div id="image-editor">${imageEditor(true)}</div><div class="upload-area"><label>上传补充或替换图片<input type="file" data-upload="note" accept="image/png,image/jpeg,image/webp" multiple><small>PNG / JPEG / WebP，单张不超过 10MB；替换可先移除旧图再上传。</small></label></div><div class="actions" style="margin-top:18px"><button class="primary" type="submit">保存图文修改</button><span id="dirty-state" class="muted">当前版本 v${n.revision}</span></div></form>${regenerationPanel(n)}<hr><label>内容审核的发布模式<select id="note-mode"><option value="normal" ${n.contentApproval?.mode!=='product'?'selected':''}>普通种草笔记</option><option value="product" ${n.contentApproval?.mode==='product'?'selected':''}>挂商品笔记</option></select></label><div id="mode-hint" class="notice subtle">${modeHint(n.contentApproval?.mode||'normal',p)}</div><details><summary>对照商品事实与原图</summary><p class="raw-note">${e(p.facts||'商品事实尚未补充')}</p><div class="uploads">${p.images.map(u=>`<div class="asset">${img(u)}</div>`).join('')}</div>${link(p.url,'商品链接')}</details><details><summary>版本记录 · ${n.revisions.length} 个版本</summary>${[...n.revisions].reverse().map(v=>`<p class="muted">v${v.revision} · ${displayTime(v.createdAt)} · ${e(v.title)}</p>`).join('')}</details></section><aside class="card note-preview"><div class="preview-account">${e(accountName(n.accountId))} · 阅读预览</div><div id="preview-images">${previewImages()}</div><h2 class="preview-title" id="preview-title">${e(n.title)}</h2><p class="preview-body" id="preview-body">${e(n.body)}</p><span class="tag">${approved(n)?'当前版本内容已通过':'当前版本待审核'}</span><p class="muted">${n.provenance==='manual-source-draft'?'手工素材草稿':'模型辅助草稿'} · 发布前仍需排期授权</p>${button('导出图文与素材清单','export',n.id)}</aside></div><div class="bar"><div><strong>${ns.filter(approved).length}/${ns.length} 篇内容通过</strong><p>本次审核：${e(n.title)} · v${n.revision}</p></div><div class="actions">${button('内容通过并查看下一篇','note-approve',n.id,true)}<a class="button" href="#schedule/${id}">为已审笔记排期 →</a></div></div>`;}
function modeHint(mode,p){return mode==='product'?`关联商品：${e(p.name)}。精确挂载尚未验证；可审核、导出素材后手动发布，不能自动排期。`:'审核通过仅确认内容；确认账号和时间后才授权发布。';}
function regenerationPanel(note){const slots=originalPlanSlots(get('topics',note.topicId));return `<details><summary>按原配图方案重新生成</summary><p class="muted">下面编号对应原方案，与上方当前图片顺序无关。成功后按原方案顺序重建生成图片列表，替换上传或重排的列表；曾移除的其他生成图也会恢复。旧图仍保留在版本记录。</p>${slots.map(item=>`<div class="plan-editor"><h3>方案 ${item.slot+1} · ${e(item.role)}</h3><p class="raw-note">${e(item.prompt)}</p>${button('重新生成此方案','plan-image-regen',String(item.slot))}</div>`).join('')||'<p class="muted">还没有配图方案。</p>'}</details>`;}
function imageEditor(note=false){return `<div class="uploads">${images.map((u,i)=>`<div class="asset">${img(u,'',`第 ${i+1} 张图片`)}<small>第 ${i+1} 张</small><div class="asset-actions">${button('←','image-left',String(i),false,i===0)}${button('→','image-right',String(i),false,i===images.length-1)}${button('移除','image-remove',String(i))}</div></div>`).join('')}</div>`;}
function previewImages(){return images.length?img(images[0],'preview-image','笔记主图')+`<div class="preview-thumbs">${images.map((u,i)=>`<button type="button" data-action="preview-image" data-id="${i}" aria-label="预览第 ${i+1} 张">${img(u)}</button>`).join('')}</div>`:'<div class="image-empty">尚未添加笔记图片</div>';}
function schedule(id){const b=get('batches',id);if(!b)throw Error('批次不存在');const ns=listNotes(id).filter(approved);return steps(b,2)+head('PUBLISH CALENDAR','安排这批内容的发布时间','北京时间 · 系统建议基于账号常用时段与每日上限，不代表最佳发布时间。',button('生成排期建议','schedule-suggest',id,false,!ns.some(n=>n.contentApproval.mode==='normal'&&!activeFor(rows('schedules'),n))))+(ns.length?`<form id="schedule-form" data-form="schedule-preview" data-id="${id}"><div class="card"><div class="row"><h2>${e(accountName(b.accountId))}</h2><span class="tag">每日上限 ${get('accounts',b.accountId)?.dailyLimit} 篇</span></div><div class="table-wrap"><table><thead><tr><th>内容版本与模式</th><th>发布时间 · 北京时间</th><th>当前状态</th></tr></thead><tbody>${ns.map(n=>{const active=activeFor(rows('schedules'),n),pending=pendingFor(rows('schedules'),n);return `<tr><td><b>${e(n.title)}</b><p>v${n.revision} · ${n.contentApproval.mode==='product'?'挂商品 / 仅手动导出':'普通种草'}</p></td><td>${n.contentApproval.mode==='product'?button('导出图文','export',n.id):active?displayTime(active.scheduledAt):`<label class="muted">选择时间<input aria-label="${e(n.title)} 发布时间" type="datetime-local" name="time-${n.id}" value="${pending?beijingInput(pending.scheduledAt):''}"></label>`}</td><td>${active?badge(active.status):pending?badge('pending'):'<span class="muted">尚未授权发布</span>'}</td></tr>`}).join('')}</tbody></table></div><p class="muted">只处理填写了时间的普通种草笔记。已授权或已发布版本不重复创建任务。挂商品模式不会自动降级。</p></div><div class="bar"><a class="button" href="#review/${id}">返回图文审核</a><button class="primary" type="submit">检查账号、版本与排期 →</button></div></form>`:empty('没有可排期的已审笔记','请先逐篇完成内容审核。',`<a class="button" href="#review/${id}">返回审核</a>`));}
function queue(){const waiting=rows('notes').filter(n=>!approved(n)),schedules=[...rows('schedules')].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return head('REVIEW & PUBLISH','审核与发布','内容通过与发布授权分开管理，每次发布都有明确的版本和时间。')+tabs('queue')+`<div class="card"><div class="section-head"><h2>待审核笔记</h2><span class="tag">${waiting.length} 篇</span></div>${waiting.length?waiting.map(n=>`<div class="batch-item"><div><h3>${e(n.title)}</h3><p>${e(productName(n.productId))} / ${e(accountName(n.accountId))} · v${n.revision}</p></div><a class="button" href="#review/${n.batchId}/${n.id}">审核内容 →</a></div>`).join(''):'<p class="muted">暂时没有待审核内容。</p>'}</div><div class="section-head"><h2>发布任务</h2><span class="muted">${schedules.length} 条记录</span></div>${schedules.length?schedules.map(scheduleCard).join(''):empty('还没有发布任务','已审核笔记确认账号与时间后，会出现在这里。')}`;}
function scheduleCard(s){const n=get('notes',s.noteId);return `<article class="card"><div class="row"><div><h3>${e(n?.title||'笔记')}</h3><p class="muted">${e(accountName(s.accountId))} · v${s.revision} · ${displayTime(s.scheduledAt)} 北京时间</p></div>${badge(s.status)}</div>${s.error?notice(s.error):''}${s.result?.url?`<p>${link(s.result.url,'查看已发布笔记')}</p>`:s.result?.id?`<p class="muted">平台回执 ID：${e(s.result.id)}；暂未返回链接。</p>`:''}<div class="actions">${s.status==='pending'?button('核对并授权','schedule-authorize',s.id,true):''}${['pending','authorized','missed'].includes(s.status)?button('重新排期','reschedule',s.id):''}${['pending','authorized'].includes(s.status)?button('取消任务','schedule-cancel',s.id):''}${s.status==='unknown'?button('人工核对结果','schedule-reconcile',s.id,true):''}${n?`<a class="button" href="#review/${n.batchId}/${n.id}">查看内容</a>`:''}</div></article>`;}
function jobs(batchId){const ids=batchId?new Set(listNotes(batchId).map(n=>n.id)):null;const list=rows('jobs').filter(j=>!ids||ids.has(j.noteId));return head('TASK PROGRESS','制作任务','成功素材会保留。结果未知的任务需人工核对费用与结果，不自动重试。',button('刷新状态','refresh'))+(batchId?`<div class="tabs"><a href="#review/${batchId}">返回批次审核 →</a><a href="#jobs">查看全部任务</a></div>`:'')+`<div class="card"><div class="metric-row"><div><strong>${list.filter(j=>j.status==='succeeded').length}</strong><span>已完成</span></div><div><strong>${list.filter(j=>['queued','submitting','submitted','processing','writing'].includes(j.status)).length}</strong><span>执行中 / 排队中</span></div><div><strong>${list.filter(j=>['failed','unknown'].includes(j.status)).length}</strong><span>需要处理</span></div></div><p class="muted">费用：尚无可验证报价，无法估算。后台运行不依赖此页面；Mac 休眠会影响任务执行。</p></div>`+(list.length?[...list].reverse().map(j=>`<article class="card job-card"><div><div class="row"><h3>${e(get('notes',j.noteId)?.title||'笔记')} · ${j.kind==='text'?'文案':`第 ${Number(j.slot)+1} 张图片`}</h3>${badge(j.status)}</div><div class="job-meta"><span>${displayTime(j.createdAt)}</span>${j.model?`<span>${e(j.model)}</span>`:''}${typeof j.progress==='number'?`<span>服务返回进度 ${e(j.progress)}%</span>`:''}<span>${j.abandonedAt?'已人工放弃写入当前笔记':''}</span></div>${j.error?notice(j.error):''}<div class="actions">${j.status==='failed'&&!j.abandonedAt?button('重试失败任务','job-retry',j.id):''}${j.status==='unknown'&&!j.abandonedAt?button('核对后放弃本次任务','job-abandon',j.id):''}<a class="button" href="#review/${get('notes',j.noteId)?.batchId}/${j.noteId}">查看笔记</a></div>${j.taskId?`<details><summary>任务回执</summary><p class="muted">${e(j.taskId)}</p></details>`:''}</div>${j.assetUrl?`<a href="${e(assetURL(j.assetUrl))}" target="_blank" rel="noopener">${img(j.assetUrl,'','已生成素材')}</a>`:''}</article>`).join(''):empty('暂无制作任务','确认选题方案并选择生成服务后，这里会显示实际任务状态。'));}
function research(){return head('DISCOVER','发现新品','从真实样本找需求与商品线索；内容热度与来源销量分别判断。',button('添加参考笔记','evidence-new')+button('导入 CSV / JSON','research-import'))+`<div class="card"><form data-form="search" class="search-row">${select('执行账号','accountId',accountOptions())}${field('检索同品类笔记','query','','text','required placeholder="例如：通勤水杯"')}<button class="primary" type="submit" ${rows('accounts').length?'':'disabled'}>搜索真实笔记</button></form>${!rows('accounts').length?'<p class="muted">请先在账号与设置中添加并绑定账号。</p>':''}</div><div class="notice subtle">持续可见的定时浏览与停留计时尚未接通。当前仅提供主动检索；不会模拟显示账号活跃时长。</div><div class="section-head"><h2>研究记录</h2><div class="actions">${button('查看候选报告','research-report')}<span class="muted">${rows('research').length} 条</span></div></div>${rows('research').length?rows('research').map(r=>`<article class="card"><div class="row"><div><div class="pill-row"><span class="tag">${r.recordType==='note-signal'?'笔记信号':'商品证据'}</span><span class="tag">${r.confirmedProductMatch?'商品匹配已确认':'待确认商品匹配'}</span></div><h2>${e(r.title||r.candidate||'研究记录')}</h2></div>${link(r.url)}</div><div class="metric-row"><div><strong>${r.metrics?.likes??'—'}</strong><span>点赞</span></div><div><strong>${r.metrics?.comments??'—'}</strong><span>评论</span></div><div><strong>${r.metrics?.collects??'—'}</strong><span>收藏</span></div><div><strong>${r.sales??'—'}</strong><span>来源声明销量</span></div></div><p class="muted">${e(r.provenance)} · 采集 ${displayTime(r.sampledAt)}<br>${e(r.scope||'仅代表当前样本')}<br>缺失：${e([r.sales==null?'成交销量':null,...['likes','comments','collects'].filter(k=>r.metrics?.[k]==null).map(k=>({likes:'点赞',comments:'评论',collects:'收藏'}[k]))].filter(Boolean).join('、')||'上述指标均有记录，采购成本、利润与供货仍待核实')}</p><div class="actions">${button(r.confirmedProductMatch?'修改商品匹配':'确认商品匹配','research-match',r.id)}${button('作为创作参考','evidence-new',r.id)}${r.feedId?button('读取笔记详情','research-detail',r.id):''}${r.feedId?button('起草互动','interaction-new',r.id):''}</div><details><summary>原始指标与来源记录</summary><pre>${e(JSON.stringify(r.raw||r,null,2))}</pre></details></article>`).join(''):empty('还没有研究证据','用关键词搜索真实笔记，或导入已有数据。没有成交证据的候选只作为潜力线索。')}`+ '<div class="section-head"><h2>创作参考库</h2><span class="muted">'+rows('evidence').length+' 条参考</span></div>' + (rows('evidence').length ? rows('evidence').map(ev=>'<article class="card"><h3>'+e(ev.title||ev.query)+'</h3><p class="raw-note">'+e(ev.excerpt||'')+'</p><p>'+link(ev.url)+'</p><p class="muted">采集 '+displayTime(ev.retrievedAt)+' · '+e(ev.provenance)+'</p></article>').join('') : '<p class="muted">添加参考笔记后，可在选题中引用真实来源。</p>');}
function settingsPage(){return head('WORKSPACE SETTINGS','账号与设置','每个账号独立绑定身份、服务端口与发布节奏。',button('＋ 添加账号','account-new','',true))+`<div class="grid">${rows('accounts').map(a=>`<article class="card"><h2>${e(a.name)}</h2><p>${e(a.positioning||'尚未填写账号定位')}</p><div class="pill-row"><span class="tag">${a.platformUserId?'身份已绑定':'身份未绑定'}</span><span class="tag">每天最多 ${a.dailyLimit} 篇</span></div><p class="muted">常用时段：${e((a.dailySlots||[]).join(' / ')||'使用全局设置')}<br>绑定 ID：${e(a.platformUserId||'尚未绑定')}</p><div class="actions">${button('编辑','account-edit',a.id)}${button('检查登录','account-status',a.id)}${button('登录二维码','account-qr',a.id)}</div></article>`).join('')}</div>${rows('accounts').length?'':empty('添加你的第一个账号','每个账号需使用独立的本地小红书服务端口，并核对返回的真实用户 ID。',button('添加账号','account-new','',true))}<div class="section-head"><h2>创作与排期默认值</h2></div><div class="two-col"><form data-form="settings" class="card"><div class="form-grid">${field('候选选题数量','topicCount',settings.topicCount,'number','min="1" max="30" required')}${field('计划制作篇数','targetCount',settings.targetCount,'number','min="1" max="30" required')}${field('每篇图片上限','maxImages',settings.maxImages,'number','min="1" max="18" required')}${select('默认出图服务','imageProvider',[['grsai','GRSai 批量出图'],['manual','手工 / Codex 出图导入']],settings.imageProvider)}${field('图片模型','imageModel',settings.imageModel)}${field('文案模型','llmModel',settings.llmModel)}<div class="full">${field('常用发布时间（北京时间，逗号分隔）','dailySlots',(settings.dailySlots||[]).join(', '),'text','placeholder="10:00, 14:00, 20:00" required')}</div></div><p class="muted">数量可以在每批调整；图数逐篇策划。服务和模型修改只影响后续任务。</p><button type="submit" class="primary">保存默认设置</button></form><aside class="card"><h2>服务配置状态</h2><div class="batch-item"><span>文案服务</span><span class="tag">${health.llmConfigured?'已配置':'未配置'}</span></div><div class="batch-item"><span>GRSai</span><span class="tag">${health.imageConfigured?'已配置':'未配置'}</span></div><div class="batch-item"><span>发布服务</span><span class="tag">${health.publisherConfigured?'已配置':'未配置'}</span></div><p class="settings-note">“已配置”不代表已经连接或验证成功。API 密钥保存在本机，保存后不回显。文案与选题执行器：${e(executorName())}。</p><p class="muted">精确挂商品：尚未验证，仅支持审核后导出。<br>持续可见定时浏览：未接通。</p></aside></div>${serviceConfigForm()}`;}
function serviceConfigForm(){return `<div class="section-head"><h2>文案与出图服务</h2></div><form data-form="config" class="card" autocomplete="off"><h3>选题与文案执行器</h3><p class="muted">使用本机 Agent 登录状态或直接调用 LLM API。保存后仅对新任务生效，执行失败不会自动切换服务。</p><div class="form-grid">${select('执行方式','provider',[['codex','Codex CLI'],['workbuddy','WorkBuddy'],['api','LLM API']],config.provider||'codex')}${field('执行超时（秒）','timeoutSeconds',config.timeoutSeconds||120,'number','min="10" max="1800" required')}${field('Codex CLI 可执行文件路径','codexPath',config.codexPath||'','text','placeholder="自动检测，可填写绝对路径"')}${field('WorkBuddy CLI 可执行文件路径','workbuddyPath',config.workbuddyPath||'','text','placeholder="自动检测，可填写绝对路径"')}${field('Runtime 模型（留空使用执行器默认值）','runtimeModel',config.runtimeModel||'')}</div><h3>LLM API</h3><p class="muted">仅在选择 LLM API 时使用。文案模型沿用上方默认设置。</p><div class="form-grid">${field('LLM API 地址','llmBaseUrl',config.llmBaseUrl||'','url','placeholder="https://…/v1"')}${field('LLM API Key','llmApiKey','','password',`autocomplete="new-password" placeholder="${config.llmApiKeySet?'已保存；留空保留':'尚未保存'}"`)}</div><label class="check"><input type="checkbox" name="clearLlmApiKey">清除已保存的 LLM API Key</label><h3>GRSai 出图</h3><p class="muted">出图服务独立于文案执行器；图片模型沿用上方默认设置。</p><div class="form-grid">${field('GRSai API 地址','grsaiBaseUrl',config.grsaiBaseUrl||'','url','placeholder="https://…"')}${field('GRSai API Key','grsaiApiKey','','password',`autocomplete="new-password" placeholder="${config.grsaiApiKeySet?'已保存；留空保留':'尚未保存'}"`)}</div><label class="check"><input type="checkbox" name="clearGrsaiApiKey">清除已保存的 GRSai API Key</label><p class="settings-note">密钥留空会保留原值；只有勾选清除才会删除。请先保存，再检查当前文案执行器。检查不会生成内容或调用付费模型，也不代表模型生成已验证成功。</p><div class="actions"><button type="submit" class="primary">保存服务配置</button>${button('检查已保存的执行器','config-check')}</div><p id="config-check-result" role="status" class="muted"></p></form>`;}
function interactions(){return head('HUMAN REVIEW','点赞与留言','逐条核对账号、目标笔记与完整留言。保存草稿、批准、执行是三个独立动作。',button('起草互动','interaction-new'))+tabs('interactions')+notice('持续可见的定时浏览尚未接通；这里不提供自动养号或批量自动互动。')+(rows('interactions').length?[...rows('interactions')].reverse().map(i=>`<article class="card"><div class="row"><h3>${e(accountName(i.accountId))} · ${i.kind==='like'?'点赞':'留言'}</h3>${badge(i.status)}</div><p>${link(i.targetUrl,'目标笔记')}</p>${i.kind==='comment'?`<p class="raw-note">${e(i.body)}</p>`:''}<p class="muted">理由：${e(i.reason)} · v${i.revision}</p>${i.error?notice(i.error):''}<div class="actions">${['draft','approved'].includes(i.status)?button('编辑草稿','interaction-edit',i.id):''}${i.status==='draft'?button('逐条审核','interaction-review',i.id,true):''}${i.status==='approved'?button('执行已批准动作','interaction-execute',i.id,true):''}${i.status==='unknown'?button('人工核对','interaction-reconcile',i.id,true):''}</div>${i.reconciliation?`<p class="muted">人工核对依据：${e(i.reconciliation.reason)}</p>`:''}</article>`).join(''):empty('没有待处理的互动','从研究笔记起草留言或点赞理由，确认后再执行。'));}

function modal(title,body,form='',id='',submit='保存'){dialogToken++;dialog.innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2>${button('×','close')}</div>${form?`<form data-form="${form}" data-id="${e(id)}">`:''}${body}<div class="dialog-error" role="alert"></div>${form?`<div class="dialog-foot">${button('取消','close')}<button class="primary" type="submit">${e(submit)}</button></div></form>`:''}`;if(!dialog.open)dialog.showModal();dialog.querySelector('input,select,textarea')?.focus();}
function closeModal(){dialogToken++;dialog.close();dialog.innerHTML='';dirty=false;}
let shopPreview=null;
function shopDialog(){shopPreview=null;if(!rows('accounts').length){modal('同步我的店铺商品','<p>请先在「账号与设置」中添加店铺所属账号。</p>'+button('关闭','close'));return;}modal('同步我的店铺商品',`${select('店铺所属账号','accountId',accountOptions())}<p class="muted">检测自己的店铺商品及上下架状态。读取成功后可一键导入，已有商品按店铺与商品 ID 去重。</p><div id="shop-preview-result" aria-live="polite"></div>`,'shop-preview','','检测店铺商品');}
function productDialog(id){const p=get('products',id)||{name:'',url:'',facts:'',images:[],confirmed:false};images=[...p.images];modal(id?'编辑商品资料':'添加商品',`${shopSourceHTML(p)}${field('商品名称','name',p.name,'text','required')}${field('商品链接','url',p.url,'url','placeholder="https://…"')}${area('已证实参数与卖点','facts',p.facts,'placeholder="例如容量、材质、尺寸、价格及有依据的卖点。尚不确定的信息请标明。"')}<p class="muted">链接作为来源保存；无法读取时可直接手动建档。商品仍由你手动在店铺上架。</p><h3>商品实拍图</h3><div id="image-editor">${imageEditor()}</div><div class="upload-area"><label>上传实拍图<input type="file" data-upload="product" accept="image/png,image/jpeg,image/webp" multiple><small>单张不超过 10MB。上传后可预览、排序或移除。</small></label></div><label class="check"><input type="checkbox" name="confirmed" ${p.confirmed?'checked':''}>我已核对商品事实与实拍图，可用于文案和配图。</label>${id?notice('修改商品资料会使相关笔记的内容批准和发布授权失效。'):''}`,'product',id);}
function accountDialog(id){const a=get('accounts',id)||{name:'',positioning:'',mcpUrl:'',dailyLimit:1,dailySlots:[]};modal(id?'编辑账号':'添加账号',`${field('账号名称','name',a.name,'text','required')}${area('账号定位与表达风格','positioning',a.positioning)}${field('本地小红书服务地址','mcpUrl',a.mcpUrl,'url','placeholder="http://127.0.0.1:18060"')}<p class="muted">每个账号需独立端口和登录会话。保存后检查登录，核对真实用户 ID 再绑定。</p><div class="form-grid">${field('每日发布上限','dailyLimit',a.dailyLimit,'number','min="1" max="30" required')}${field('常用时段（逗号分隔）','dailySlots',(a.dailySlots||[]).join(', '),'text','placeholder="10:00, 20:00"')}</div>${a.platformUserId?notice('当前绑定 ID：'+a.platformUserId+'。修改连接地址后需要重新核对身份，已有发布授权会失效。'):''}`,'account',id);}
function batchDialog(productId){if(!rows('accounts').length){toast('请先添加至少一个账号',true);navigate('settings');return;}modal('创建创作批次',`<p>商品：<b>${e(productName(productId))}</b></p>${select('目标账号','accountId',accountOptions())}<div class="form-grid">${field('候选选题数量','topicCount',settings.topicCount,'number','min="1" max="30" required')}${field('计划制作篇数','targetCount',settings.targetCount,'number','min="1" max="30" required')}</div><p class="muted">一个批次对应一个账号。计划篇数仅供参考，不限制最终选中数量。</p>`,'batch',productId,'创建并策划选题');}
function topicDialog(id){const t=get('topics',id);plan=structuredClone(t.imagePlan||[{role:'',prompt:''}]);modal('编辑选题与配图方案',`${field('标题方向','title',t.title,'text','required')}${field('目标人群','audience',t.audience)}${area('场景与内容切入点','angle',t.angle)}${area('商品事实依据','factBasis',t.factBasis)}${field('图片数量的理由','imageCountReason',t.imageCountReason)}<details><summary>参考证据</summary>${rows('evidence').length?rows('evidence').map(ev=>`<label class="check"><input type="checkbox" name="evidenceIds" value="${e(ev.id)}" ${(t.evidenceIds||[]).includes(ev.id)?'checked':''}>${e(ev.title||ev.excerpt||ev.url||ev.id)}</label>`).join(''):'<p class="muted">暂无已保存的创作参考证据；不会虚构引用来源。</p>'}</details><div class="row"><h3>逐张配图方案</h3><span class="muted">最多 ${settings.maxImages} 张</span></div><div id="plan-editor">${planEditor()}</div>${button('＋ 增加一张','plan-add')}<p class="muted">保存修改会撤销该选题的确认，需要重新确认后生成。费用暂不可估算。</p>`,'topic',id,'保存方案');}
function planEditor(){return plan.map((p,i)=>`<div class="plan-editor"><div class="row"><h3>第 ${i+1} 张</h3>${button('删除','plan-remove',String(i),false,plan.length===1)}</div>${field('图片用途',`role-${i}`,p.role,'text','required placeholder="例如：封面 / 使用场景 / 细节"')}${area('画面要求与生成描述',`prompt-${i}`,p.prompt,'required placeholder="描述商品、构图、场景、要表达的信息及需要保留的外观特征。"')}</div>`).join('');}
function capturePlan(){plan=plan.map((p,i)=>({role:dialog.querySelector(`[name="role-${i}"]`)?.value||'',prompt:dialog.querySelector(`[name="prompt-${i}"]`)?.value||''}));}
function generateDialog(id){const ts=rows('topics').filter(t=>t.batchId===id&&t.confirmed);modal('确认制作服务',`<p>已确认 <b>${ts.length}</b> 篇选题，共 <b>${ts.reduce((v,t)=>v+t.imagePlan.length,0)}</b> 张图片规划。</p>${select('图片制作方式','provider',[['grsai','GRSai 自动生成'],['manual','手工 / Codex 出图后上传']],settings.imageProvider)}${select('文案制作方式','textProvider',[['llm',executorName()+' 生成文案'],['manual','手工撰写']], 'llm')}<p class="muted">${e(executorName())}：${health.llmConfigured?'已配置':'未配置'} · GRSai：${health.imageConfigured?'已配置':'未配置'}</p>${notice('费用暂不可估算。自动生成可能产生供应方费用；确认后仅创建内容，不授权发布。未配置服务会报错，不自动回退。')}<label class="check"><input name="ack" type="checkbox" required>我已确认这些选题与配图方案，并同意按所选方式开始制作。</label>`,'generate',id,'开始制作');}
function interactionDialog(id,edit=false){const r=edit?get('interactions',id):get('research',id);modal(edit?'编辑互动草稿':'起草单条互动',`${edit?`<p>账号：${e(accountName(r.accountId))}</p>`:select('执行账号','accountId',accountOptions(),r?.accountId)}${select('动作','kind',[['comment','留言'],['like','点赞']],r?.kind||'comment')}${field('目标笔记链接','targetUrl',r?.targetUrl||r?.url||'','url','required')}${field('笔记 ID','feedId',r?.feedId||'','text','required')}${field('访问令牌（来自真实搜索结果）','xsecToken',r?.xsecToken||'','text','required')}${area('完整留言（点赞时留空）','body',edit?r.body:'')}${area('互动理由','reason',edit?r.reason:'','required')}<p class="muted">保存仅创建草稿。你还需逐条批准，之后才可执行。</p>`,'interaction',edit?id:'','保存草稿');}
function reconcileDialog(kind,id){modal('人工核对执行结果',`${select('核对结论','outcome',[['succeeded','已成功'],['failed','已确认未成功']],'succeeded')}${kind==='schedule'?field('已发布笔记链接（成功时必填）','url','','url','placeholder="https://www.xiaohongshu.com/…"'):''}${area('核对依据','reason','','required placeholder="说明在哪个页面、何时检查了什么结果。"')}`,'reconcile-'+kind,id,'保存核对结果');}
let identityResult=null, scheduleSelection=[];
function reviewSchedule(items){scheduleSelection=items;modal('最终发布授权',`<p>以下授权仅适用于列出的账号、内容版本、商品模式与精确时间。</p><div class="table-wrap"><table><thead><tr><th>账号与内容</th><th>授权时间（北京）</th></tr></thead><tbody>${items.map(x=>{const n=get('notes',x.noteId);return `<tr><td><b>${e(n.title)}</b><p>${e(accountName(x.accountId))} · v${n.revision} · 普通种草</p></td><td>${displayTime(x.scheduledAt)}</td></tr>`}).join('')}</tbody></table></div><label class="check"><input type="checkbox" name="ack" required>我已逐篇审核上述内容，确认账号和时间，授权系统到点发布。</label>`,'authorize','','确认并授权发布');}
async function act(action,id,el){
 switch(action){
 case 'close': if(dirty&&!confirm('放弃尚未保存的修改吗？'))return;closeModal();break;
 case 'refresh': if(dirty&&!confirm('更新页面会放弃尚未保存的修改，继续吗？'))return;await refresh();break;
 case 'shop-open': shopDialog();break;
 case 'shop-import': {if(!shopPreview)throw Error('请先检测店铺商品');const result=await api(`accounts/${shopPreview.accountId}/shop-import`,'POST',{token:shopPreview.token});shopPreview=null;closeModal();await refresh();toast(`已新增 ${result.created} 件商品，更新 ${result.updated} 件状态`);break;}
 case 'product-new': productDialog();break;
 case 'product-edit': productDialog(id);break;
 case 'account-new': accountDialog();break;
 case 'account-edit': accountDialog(id);break;
 case 'batch-new': batchDialog(id);break;
 case 'topic-edit': topicDialog(id);break;
 case 'topic-add': modal('手工添加选题',`${area('每行一个选题标题','titles','','required placeholder="请填写真实内容方向，不需要凑满计划数量。"')}<p class="muted">添加后逐一完善目标人群、事实依据和配图方案。</p>`,'topic-add',id,'添加选题');break;
 case 'plan': if(!health.llmConfigured)throw Error('文案执行器未配置。请在账号与设置中配置执行器并检查可用性。');await api(`batches/${id}/plan`,'POST',{});await refresh();toast('选题方案已生成，请逐一核对');break;
 case 'config-check': {if(dirty)throw Error('请先保存服务配置，再检查已保存的执行器');const result=await api('config/check','POST',{});const output=document.querySelector('#config-check-result');if(output)output.textContent=result.message;toast(result.message,!result.ok);break;}
 case 'topic-confirm': await api(`topics/${id}/confirm`,'POST',{});await refresh();toast('选题与配图方案已确认');break;
 case 'topic-unconfirm': await api(`topics/${id}`,'PATCH',{});await refresh();toast('已撤销选题确认');break;
 case 'plan-add': capturePlan();if(plan.length>=settings.maxImages)throw Error('已达到每篇图片上限，可在设置中调整');plan.push({role:'',prompt:''});dialog.querySelector('#plan-editor').innerHTML=planEditor();dirty=true;break;
 case 'plan-remove': capturePlan();if(plan.length<=1)throw Error('至少保留一张配图方案');plan.splice(Number(id),1);dialog.querySelector('#plan-editor').innerHTML=planEditor();dirty=true;break;
 case 'generate-dialog': generateDialog(id);break;
 case 'image-left': case 'image-right': case 'image-remove': {const index=Number(id);if(action==='image-remove')images.splice(index,1);else{const other=action==='image-left'?index-1:index+1;if(other>=0&&other<images.length)[images[index],images[other]]=[images[other],images[index]];}updateImageEditor();markDirty();break;}
 case 'preview-image': {const image=main.querySelector('.preview-image');if(image&&assetURL(images[Number(id)]))image.src=images[Number(id)];break;}
 case 'plan-image-regen': {if(dirty)throw Error('请先保存图文修改，再按方案生成');const n=get('notes',editingNote);if(!n)throw Error('笔记不存在');const entry=originalPlanSlots(get('topics',n.topicId)).find(item=>item.slot===Number(id));if(!entry)throw Error('原配图方案不存在，请刷新后重试');if(!confirm(`重新生成方案 ${entry.slot+1}「${entry.role}」？\n成功后将按原方案顺序重建生成图片列表，替换当前上传或重排的列表；曾移除的其他生成图也会恢复。旧图保留在版本记录。可能产生费用并使批准失效。`))return;await api(`notes/${n.id}/regenerate`,'POST',{slot:entry.slot});await refresh();toast('已按原配图方案创建生成任务');break;}
 case 'note-approve': {if(dirty)throw Error('有未保存修改，请先保存再审核');const n=get('notes',id),mode=main.querySelector('#note-mode').value;await api(`notes/${id}/approve`,'POST',{mode,...(mode==='product'?{productId:n.productId}:{})});await load();const ns=listNotes(n.batchId),index=ns.findIndex(x=>x.id===id),next=ns[index+1]||ns.find(x=>!approved(x))||ns[index];navigate(`review/${n.batchId}/${next.id}`);toast('内容通过，尚未授权发布');break;}
 case 'export': {if(dirty)throw Error('请先保存当前修改后再导出');const output=await api(`notes/${id}/export`);const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rednote-${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);modal('图文与素材导出',`<p>已下载图文清单。点击下方图片可打开原始素材并保存。</p><h3>${e(output.title)}</h3><p class="raw-note">${e(output.body)}</p><div class="uploads">${output.images.map((x,i)=>assetURL(x.url)?`<a class="asset" href="${e(x.url)}" download="${e(x.filename||`image-${i+1}`)}">${img(x.url)}<small>下载第 ${i+1} 张</small></a>`:'').join('')}</div>${output.manualRequired?notice('此笔记为挂商品模式，请手动发布并核对商品购买入口。'):''}`);break;}
 case 'schedule-suggest': {const b=get('batches',id),ns=listNotes(id).filter(n=>approved(n)&&n.contentApproval.mode==='normal'&&!activeFor(rows('schedules'),n)&&!pendingFor(rows('schedules'),n));if(!ns.length)throw Error('没有尚未排期的已审普通种草笔记');const result=await api('schedules/suggest','POST',{accountId:b.accountId,noteIds:ns.map(n=>n.id),days:14});for(const s of result.suggestions){const input=main.querySelector(`[name="time-${s.noteId}"]`);if(input)input.value=beijingInput(s.scheduledAt);}dirty=true;toast(result.unscheduled?`已建议 ${result.suggestions.length} 篇，还有 ${result.unscheduled} 篇需要调整时段`:'已填入建议时间，请检查后授权');break;}
 case 'schedule-authorize': {const s=get('schedules',id);reviewSchedule([s]);break;}
 case 'schedule-cancel': if(!confirm('取消这条尚未执行的发布任务吗？'))return;await api(`schedules/${id}/cancel`,'POST',{});await refresh();toast('任务已取消');break;
 case 'reschedule': {const s=get('schedules',id);modal('重新排期',`${field('新的发布时间 · 北京时间','scheduledAt',beijingInput(s.scheduledAt),'datetime-local','required')}<p class="muted">保存后旧发布授权失效，需要重新核对并授权。</p>`,'reschedule',id,'保存新排期');break;}
 case 'schedule-reconcile': reconcileDialog('schedule',id);break;
 case 'job-retry': if(!confirm('仅重试这条失败任务？可能产生供应方费用。'))return;await api(`jobs/${id}/retry`,'POST',{});await refresh();toast('已重新提交失败任务');break;
 case 'job-abandon': modal('核对后放弃未知任务',`${area('人工核对结果与放弃原因','reason','','required')}<p class="muted">放弃不会退回供应方费用。若之后拿到素材，会保留在任务记录中，不覆盖当前笔记。</p>`,'job-abandon',id,'确认放弃');break;
 case 'account-status': {const a=get('accounts',id),result=await api(`accounts/${id}/status`);identityResult={id,userId:typeof result.user_id==='string'||typeof result.user_id==='number'?String(result.user_id):'',logged:result.is_logged_in===true};modal('核对登录身份',`<p>工作台账号：<b>${e(a.name)}</b></p><div class="identity-result"><p>登录状态：${result.is_logged_in?'已登录':'未登录'}</p><p>服务返回用户 ID：<b>${e(identityResult.userId||'未返回')}</b></p><p>当前绑定用户 ID：${e(a.platformUserId||'未绑定')}</p></div>${identityResult.logged&&identityResult.userId&&identityResult.userId!==a.platformUserId?`<p>请核对这确实是你要用于该工作台账号的身份。更换身份会撤销相关发布和互动授权。</p>${button('确认绑定此真实用户 ID','account-bind',id,true)}`:identityResult.logged&&identityResult.userId===a.platformUserId?'<p class="muted">返回身份与绑定一致。</p>':'<p class="muted">未拿到已登录的真实用户 ID，不能绑定。请先登录或检查服务返回。</p>'}`);break;}
 case 'account-bind': if(!identityResult||identityResult.id!==id||!identityResult.logged||!identityResult.userId)throw Error('没有可绑定的真实身份，请重新检查登录');await api(`accounts/${id}`,'PATCH',{platformUserId:identityResult.userId});identityResult=null;closeModal();await refresh();toast('已明确绑定核对过的用户 ID');break;
 case 'account-qr': {const result=await api(`accounts/${id}/qrcode`),raw=result.img||result.image||result.qrcode||result.qr_code||'',qr=/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(raw)?raw:/^[A-Za-z0-9+/=]{40,}$/.test(raw)?'data:image/png;base64,'+raw:'';modal('扫码登录',`${qr?`<img class="qr" src="${e(qr)}" alt="小红书登录二维码">`:result.is_logged_in?'<p>该会话已登录。</p>':'<p>服务未返回可显示的二维码，请检查本地小红书服务。</p>'}<p class="muted">完成登录后检查身份并明确绑定；扫码不会自动修改账号归属。</p>${button('检查登录身份','account-status',id,true)}`);break;}
 case 'research-import': modal('导入研究数据',`<label>选择 CSV 或 JSON 文件<input type="file" id="research-file" accept=".csv,.json,text/csv,application/json"></label>${select('数据格式','format',[['csv','CSV'],['json','JSON 数组']],'csv')}${area('数据内容','content','','required')}<p class="muted">必填字段：category、candidate、url、sampledAt。可选：likes、comments、collects、sales。时间请含时区，例如 2026-10-06T10:00:00+08:00。销量仅标记为来源声明。</p>`,'research-import','','导入证据');break;
 case 'evidence-new': {const r=get('research',id);modal('添加创作参考',`${field('参考标题','title',r?.title||r?.candidate||'','text','required')}${field('检索词或研究主题','query',r?.query||r?.category||'','text','required')}${field('来源链接','url',r?.url||'','url','required')}${area('可借鉴内容与证据摘录','excerpt','','required placeholder="记录可借鉴的表达结构与真实证据，不直接照搬原文。"')}${select('关联账号','accountId',accountOptions(),r?.accountId)}<p class="muted">保存后可在选题方案中引用，模型规划也会读取这些参考。</p>`,'evidence','','保存参考');break;}
 case 'research-match': {const r=get('research',id);modal('确认商品匹配',`<p>${e(r.title||r.candidate||'研究记录')}</p>${link(r.url,'查看匹配来源')}${field('候选商品名称','candidate',r.candidate||'','text','required')}${field('品类','category',r.category==='搜索'?'':r.category,'text','required')}<label class="check"><input type="checkbox" name="ack" required>我已核对来源，这条记录确实对应上述商品。</label>`,'research-match',id,'确认匹配');break;}
 case 'research-report': {report=await api('research/report');modal('候选商品报告',`<p class="muted">${e(report.scope)}</p>${report.groups.length?report.groups.map(g=>`<h2>${e(g.category)}</h2>${[['heatRanking','内容热度排行','heat'],['salesRanking','来源声明销量排行','sales'],['unknown','数据不足候选',null]].map(([key,title,metric])=>`<h3 style="margin-top:20px">${title}</h3>${g[key].length?`<div class="table-wrap"><table><thead><tr><th>候选商品</th><th>${metric==='heat'?'互动合计':metric==='sales'?'来源销量':'指标'}</th><th>样本</th></tr></thead><tbody>${g[key].map(x=>`<tr><td>${e(x.candidate)}<p>${link(x.sourceUrl)}</p></td><td>${metric?e(x[metric]):'缺失'}</td><td>${x.samples} 次<br>${displayTime(x.latestAt)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">暂无足够数据。</p>'}`).join('')}`).join(''):'<p>尚无已确认匹配的商品。请先核对研究记录。</p>'}<p class="muted">未确认笔记信号 ${report.noteSignals.length} 条。热度不等于成交；单次快照不推断增长。</p>`);break;}
 case 'research-detail': {const r=get('research',id);const data=await api('research/detail','POST',{accountId:r.accountId,feedId:r.feedId,xsecToken:r.xsecToken});modal('笔记详情 · 服务原始返回',`<p>${link(r.url,'打开笔记')}</p><pre>${e(JSON.stringify(data,null,2))}</pre>`);break;}
 case 'interaction-new': if(!rows('accounts').length)throw Error('请先添加执行账号');interactionDialog(id);break;
 case 'interaction-edit': interactionDialog(id,true);break;
 case 'interaction-review': {const i=get('interactions',id);modal('逐条审核互动',`<p>账号：<b>${e(accountName(i.accountId))}</b> · 动作：${i.kind==='like'?'点赞':'留言'}</p><p>${link(i.targetUrl,'目标笔记')}</p>${i.kind==='comment'?`<h3>完整留言</h3><p class="raw-note">${e(i.body)}</p>`:''}<p>理由：${e(i.reason)}</p><p class="muted">批准后仍需点击执行。修改目标或留言会使本次批准失效。</p><label class="check"><input name="ack" type="checkbox" required>我确认上述账号、目标和具体动作。</label>`,'interaction-approve',id,'批准此条互动');break;}
 case 'interaction-execute': {const i=get('interactions',id);if(!confirm(`现在用「${accountName(i.accountId)}」执行已批准的${i.kind==='like'?'点赞':'留言'}？`))return;const result=await api(`interactions/${id}/execute`,'POST',{});await refresh();toast(result.status==='succeeded'?'服务返回执行成功':'执行结果需要人工核对',result.status!=='succeeded');break;}
 case 'interaction-reconcile': reconcileDialog('interaction',id);break;
 }
}

async function submit(form){const data=Object.fromEntries(new FormData(form)),id=form.dataset.id,kind=form.dataset.form;
 switch(kind){
 case 'shop-preview': {shopPreview=null;const panel=dialog.querySelector('#shop-preview-result');panel.textContent='正在检测店铺并读取商品…';try{const result=await api(`accounts/${data.accountId}/shop-preview`,'POST',{});shopPreview={...result,accountId:data.accountId};panel.innerHTML=shopPreviewHTML(result)+(result.products.length?button('一键导入并更新状态','shop-import','',true):'');dirty=false;}catch(error){panel.textContent='检测未完成，未导入任何商品。';throw error;}break;}
 case 'product': {const payload={name:data.name.trim(),url:data.url.trim(),facts:data.facts,images:[...images],confirmed:data.confirmed==='on'};if(payload.url&&!safeURL(payload.url))throw Error('商品链接须为有效 HTTP(S) 地址');if(payload.confirmed&&(!payload.facts.trim()||!payload.images.length))throw Error('请补充商品事实与实拍图后再确认资料');await api('products'+(id?'/'+id:''),id?'PATCH':'POST',payload);closeModal();await refresh();toast('商品资料已保存');break;}
 case 'account': await api('accounts'+(id?'/'+id:''),id?'PATCH':'POST',{name:data.name,positioning:data.positioning,mcpUrl:data.mcpUrl.trim(),dailyLimit:Number(data.dailyLimit),dailySlots:data.dailySlots.split(/[,，\s]+/).filter(Boolean)});closeModal();await refresh();toast('账号已保存，请检查登录身份');break;
 case 'batch': {const b=await api('batches','POST',{productId:id,accountId:data.accountId,topicCount:Number(data.topicCount),targetCount:Number(data.targetCount)});closeModal();await load();navigate('batch/'+b.id);break;}
 case 'topic-add': await api(`batches/${id}/topics`,'POST',{titles:data.titles.split('\n').map(v=>v.trim()).filter(Boolean)});closeModal();await refresh();toast('已添加选题，请完善逐张配图方案');break;
 case 'topic': capturePlan();await api(`topics/${id}`,'PATCH',{title:data.title,audience:data.audience,angle:data.angle,factBasis:data.factBasis,imageCountReason:data.imageCountReason,evidenceIds:new FormData(form).getAll('evidenceIds'),imagePlan:plan});closeModal();await refresh();toast('方案已保存，请重新确认选入');break;
 case 'generate': {if(data.provider==='grsai'&&!health.imageConfigured)throw Error('GRSai 未配置，请配置后重试或明确选择手工上传');if(data.textProvider==='llm'&&!health.llmConfigured)throw Error('文案服务未配置，请配置后重试或明确选择手工撰写');await api(`batches/${id}/generate`,'POST',{provider:data.provider,textProvider:data.textProvider});closeModal();await load();navigate(`review/${id}`);toast('制作批次已创建，生成状态可在任务进度查看');break;}
 case 'note': await api(`notes/${id}`,'PATCH',{title:data.title,body:data.body,images:[...images]});dirty=false;await refresh();toast('新版本已保存，需重新审核');break;
 case 'schedule-preview': {const items=[];for(const n of listNotes(id).filter(approved)){const value=data['time-'+n.id];if(!value||n.contentApproval.mode!=='normal')continue;items.push({noteId:n.id,accountId:n.accountId,mode:'normal',scheduledAt:fromBeijing(value),revision:n.revision});}if(!items.length)throw Error('请至少为一篇已审普通种草笔记填写时间');if(items.some(s=>Date.parse(s.scheduledAt)<=Date.now()))throw Error('发布时间必须晚于当前时间');dirty=false;reviewSchedule(items);break;}
 case 'authorize': {let done=0;for(const item of scheduleSelection){await load();const n=get('notes',item.noteId);if(!n||!approved(n)||n.revision!==item.revision)throw Error('笔记版本或审核状态已变化，请重新审核');const existing=activeFor(rows('schedules'),n);if(existing){if(existing.status==='authorized'&&existing.scheduledAt===item.scheduledAt){done++;continue;}throw Error('该笔记版本已有执行或发布记录，请先核对任务');}let pending=pendingFor(rows('schedules'),n);if(pending&&pending.scheduledAt!==item.scheduledAt)pending=await api(`schedules/${pending.id}`,'PATCH',{scheduledAt:item.scheduledAt});if(!pending)pending=await api('schedules','POST',{noteId:n.id,accountId:item.accountId,mode:'normal',scheduledAt:item.scheduledAt});await api(`schedules/${pending.id}/approve`,'POST',{});done++;}closeModal();await load();navigate('queue');toast(`已授权 ${done} 篇笔记定时发布`);break;}
 case 'reschedule': await api(`schedules/${id}`,'PATCH',{scheduledAt:fromBeijing(data.scheduledAt)});closeModal();await refresh();toast('新时间已保存，请重新核对并授权');break;
 case 'reconcile-schedule': case 'reconcile-interaction': {const collection=kind==='reconcile-schedule'?'schedules':'interactions';await api(`${collection}/${id}/reconcile`,'POST',data);closeModal();await refresh();toast('人工核对结果已保存');break;}
 case 'job-abandon': await api(`jobs/${id}/abandon`,'POST',{reason:data.reason});closeModal();await refresh();toast('已记录人工放弃原因');break;
case 'settings': await api('settings','PATCH',{topicCount:Number(data.topicCount),targetCount:Number(data.targetCount),maxImages:Number(data.maxImages),imageProvider:data.imageProvider,imageModel:data.imageModel,llmModel:data.llmModel,dailySlots:data.dailySlots.split(/[,，\s]+/).filter(Boolean)});dirty=false;await refreshSettings(form);toast('默认设置已保存');break;
 case 'config': {if((data.clearLlmApiKey==='on'&&data.llmApiKey.trim())||(data.clearGrsaiApiKey==='on'&&data.grsaiApiKey.trim()))throw Error('请不要同时填写新密钥并勾选清除');await api('config','PATCH',{provider:data.provider,codexPath:data.codexPath.trim(),workbuddyPath:data.workbuddyPath.trim(),runtimeModel:data.runtimeModel.trim(),timeoutSeconds:Number(data.timeoutSeconds),llmBaseUrl:data.llmBaseUrl.trim(),grsaiBaseUrl:data.grsaiBaseUrl.trim(),llmApiKey:data.llmApiKey.trim(),grsaiApiKey:data.grsaiApiKey.trim(),clearLlmApiKey:data.clearLlmApiKey==='on',clearGrsaiApiKey:data.clearGrsaiApiKey==='on'});form.querySelectorAll('input[type="password"]').forEach(input=>{input.value='';});dirty=false;await refreshSettings(form);toast('服务配置已保存，后续新任务将使用此配置');break;}
 case 'search': {const result=await api('research/search','POST',{accountId:data.accountId,query:data.query});dirty=false;await refresh();toast(`已保存 ${result.length} 条真实笔记信号`);break;}
 case 'research-import': {let payload;if(data.format==='json'){let parsed;try{parsed=JSON.parse(data.content);}catch{throw Error('JSON 格式错误，请提供数组');}if(!Array.isArray(parsed))throw Error('JSON 顶层须为记录数组');payload={rows:parsed};}else payload={csv:data.content};const result=await api('research/import','POST',payload);closeModal();await refresh();toast(`已导入 ${result.length} 条证据`);break;}
 case 'research-match': await api(`research/${id}`,'PATCH',{candidate:data.candidate,category:data.category,confirmedProductMatch:true});closeModal();await refresh();toast('商品匹配已确认，可进入候选报告');break;
 case 'evidence': if(!safeURL(data.url))throw Error('来源须为有效 HTTP(S) 链接');await api('evidence','POST',data);closeModal();await refresh();toast('创作参考已保存，可在选题中引用');break;
 case 'interaction': {const payload={kind:data.kind,targetUrl:data.targetUrl,feedId:data.feedId,xsecToken:data.xsecToken,body:data.body,reason:data.reason};if(!id)payload.accountId=data.accountId;await api('interactions'+(id?'/'+id:''),id?'PATCH':'POST',payload);closeModal();await load();navigate('interactions');toast('草稿已保存，等待逐条审核');break;}
 case 'interaction-approve': await api(`interactions/${id}/approve`,'POST',{});closeModal();await refresh();toast('该条互动已批准，尚未执行');break;
 }
}
function updateImageEditor(){const container=document.querySelector('#image-editor');if(container)container.innerHTML=imageEditor(Boolean(editingNote)&&!dialog.open);const preview=document.querySelector('#preview-images');if(preview)preview.innerHTML=previewImages();const count=document.querySelector('#image-count');if(count)count.textContent=images.length+' 张';}
function markDirty(){dirty=true;const label=document.querySelector('#dirty-state');if(label){label.textContent='有未保存修改';label.className='dirty-label';}const approve=document.querySelector('[data-action="note-approve"]');if(approve)approve.disabled=true;}
function uploadOwner(){return {page:location.hash,noteId:editingNote,dialogToken:dialog.open?dialogToken:null};}
async function upload(input){if(!input.files?.length)return;const owner=uploadOwner(),files=[...input.files];for(const f of files){if(f.size>10*1024*1024)throw Error(`${f.name} 超过 10MB`);if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('仅支持 PNG、JPEG、WebP');}for(const f of files){const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('文件读取失败'));reader.readAsDataURL(f);});if(!sameUploadOwner(owner,uploadOwner()))throw Error('编辑对象已变化，已停止上传关联');const a=await api('assets','POST',{base64});if(!sameUploadOwner(owner,uploadOwner()))throw Error('素材已保存，但编辑对象已变化，未关联到任何商品或笔记');images.push(a.url);updateImageEditor();markDirty();}input.value='';toast('素材已上传，请保存资料或笔记');}
async function run(fn,el){if(busy)return;busy=true;const controls=[...document.querySelectorAll('button,input[type=file]')].map(node=>[node,node.disabled]);controls.forEach(([node])=>node.disabled=true);const old=el?.textContent;if(el?.tagName==='BUTTON'){el.textContent='处理中…';el.setAttribute('aria-busy','true');}try{await fn();}catch(error){toast(error.message||'操作失败，请稍后重试',true);const target=dialog.open?dialog.querySelector('.dialog-error'):null;if(target)target.textContent=error.message;}finally{busy=false;controls.forEach(([node,disabled])=>{if(node.isConnected)node.disabled=disabled;});if(el?.isConnected&&el.tagName==='BUTTON'){el.textContent=old;el.removeAttribute('aria-busy');}if(dirty&&editingNote){const approval=document.querySelector('[data-action="note-approve"]');if(approval)approval.disabled=true;}}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();run(()=>act(el.dataset.action,el.dataset.id,el),el);return;}const a=event.target.closest('a[href^="#"]');if(a&&busy){event.preventDefault();toast('操作正在进行，请完成后再切换页面');return;}if(a&&dirty){event.preventDefault();navigate(a.getAttribute('href').slice(1));}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();run(()=>submit(form),event.submitter);});
document.addEventListener('input',event=>{if(event.target.closest('form')){event.target.closest('form').dataset.unsaved='true';markDirty();}if(event.target.name==='title'&&event.target.closest('#note-form'))document.querySelector('#preview-title').textContent=event.target.value;if(event.target.name==='body'&&event.target.closest('#note-form'))document.querySelector('#preview-body').textContent=event.target.value;});
document.addEventListener('change',event=>{const input=event.target;if(input.name==='accountId'&&input.closest('[data-form="shop-preview"]')){shopPreview=null;dialog.querySelector('#shop-preview-result').innerHTML='';}if(input.dataset.upload){run(()=>upload(input),input);return;}if(input.id==='note-mode'){const n=get('notes',editingNote);document.querySelector('#mode-hint').innerHTML=modeHint(input.value,get('products',n.productId));}if(input.id==='research-file'){run(async()=>{const f=input.files[0];if(!f)return;if(f.size>900000)throw Error('导入文件过大，请拆分为小于 900KB 的文件');dialog.querySelector('[name="content"]').value=await f.text();dialog.querySelector('[name="format"]').value=f.name.endsWith('.json')?'json':'csv';dirty=true;},input);}});
dialog.addEventListener('cancel',event=>{if(busy||(dirty&&!confirm('放弃尚未保存的修改吗？'))){event.preventDefault();return;}dirty=false;});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{if(location.hash===renderedHash)return;if(!allowHashNavigation({busy,dirty,currentHash:renderedHash,nextHash:location.hash,confirmDiscard:()=>confirm('当前有未保存的修改，确定离开并放弃吗？')})){history.replaceState(history.state,'',location.pathname+location.search+renderedHash);return;}render();window.scrollTo(0,0);});
document.querySelector('#refresh-button').addEventListener('click',()=>run(()=>act('refresh')));
async function poll(){if(busy||document.hidden)return;try{const next=await api('state');if(JSON.stringify(next)!==pollVersion)document.querySelector('#update-banner').hidden=false;document.querySelector('#connection').textContent='本地服务在线 · 后台任务持续运行';}catch{document.querySelector('#connection').textContent='本地服务暂不可用 · 正在等待恢复';}}
try{await load();render();}catch(error){main.innerHTML=`<div class="screen-error"><h2>暂时无法连接本地工作台</h2><p>${e(error.message)}</p>${button('重新连接','refresh','',true)}</div>`;document.querySelector('#connection').textContent='本地连接中断';}
setInterval(poll,6000);
